var a=[{title:`Perché le spalle variano`,text:`La spalla ha un ampio range di movimento e si affida a molti muscoli per restare stabile. Raggiungere in alto sopra la testa, le posizioni profonde di distensione e i movimenti veloci possono sembrare molto diversi da una persona all’altra. Un movimento limitato o doloroso ti dice qualcosa su quali esercizi scegliere. Non dimostra che tu abbia un particolare infortunio.`},{title:`Adatta l’esercizio`,text:`Se una distensione sopra la testa con bilanciere ti dà fastidio, prova una distensione con manubri a presa neutra, un rematore con appoggio o un push-up al muro. Cambia profondità o direzione prima di aggiungere resistenza. Gli esercizi di trazione sono un buon complemento per le distensioni, ma nessun rapporto fisso tra spinta e trazione cura il dolore alla spalla.`},{title:`Controllo ed esposizione graduale`,text:`Mentre impari un movimento, usa ripetizioni lente e controllate, un range comodo e carichi leggeri. Sviluppare la forza della spalla può richiedere un lavoro gradualmente più duro, ma quella progressione non dovrebbe peggiorare i tuoi sintomi. Forzare uno stretching attraverso il dolore o testare ripetutamente pesanti sollevamenti sopra la testa non ti porterà lì più in fretta.`},{title:`Segnali d’allarme`,text:`Chiedi subito un parere medico per un dolore forte dopo una caduta, un braccio che non riesci a muovere, una deformità visibile, un gonfiore importante o un nuovo intorpidimento che non passa. Anche i sintomi che non migliorano richiedono che un professionista li valuti.`},{title:`Usare TrainUp`,text:`Aggiungi la spalla tra le limitazioni in Profilo, con delle note, e tieni aggiornato l’elenco della tua attrezzatura. Il piano sceglie quindi solo esercizi adatti alle tue limitazioni, alla tua attrezzatura, al tuo livello e alla tua coordinazione. Se un esercizio fa male durante un allenamento, tocca «Sento dolore» per terminarlo subito. Resta fuori dai tuoi piani finché non lo riprendi dal Profilo. Sostituire gli esercizi in questo modo non tratta il conflitto subacromiale, la malattia della cuffia dei rotatori né alcuna altra condizione specifica.`}];var o=[{label:`NHS: dolore alla spalla e segnali d’allarme`,url:`https://www.nhs.uk/symptoms/shoulder-pain/`},{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var t={sections:a,sources:o};export{t as default,a as sections,o as sources};